package com.axelsarassamit.ridedeck.dash;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import android.text.InputType;import java.io.File;
public final class SocialSettingsActivity extends Activity {
 DashSettings settings;LinearLayout page;ScrollView scroll;android.view.View savedAnchor;
 public void onCreate(Bundle b){RideAppearance.prepare(this); super.onCreate(b);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 protected void onResume(){super.onResume();show();}
 void show(){int previousScroll=scroll==null?0:scroll.getScrollY();settings=new DashSettings(this);page=DashUi.page(this);scroll=new ScrollView(this);scroll.addView(page);setContentView(scroll);DashUi.text(this,page,"Social video studio",28);DashUi.text(this,page,"Make a ready-to-share copy for TikTok, Instagram or Facebook. Your original video and recording settings stay saved. Sharing opens your phone's chooser; you decide where to post.",16);
  String chosen=getIntent().getStringExtra("clip");if(chosen!=null)preview(new File(chosen));
  heading("PLATFORM & STYLE");DashUi.text(this,page,settings.text("social_name","TikTok video · Quick highlight"),20);
  DashUi.button(this,page,"Choose platform",v->new AlertDialog.Builder(this).setTitle("Where will you share?").setItems(SocialProfile.PLATFORMS,(d,i)->{settings.put("social_platform",i);settings.put("social_ratio",SocialProfile.ratio(i));settings.put("social_quality",1080);settings.put("social_bitrate",8);settings.put("social_fit",0);settings.put("social_start",0);settings.put("social_mute",0);applyStyle(i==2||i==5?0:i==7?3:0);}).show());
  DashUi.button(this,page,"Choose a purpose preset",v->new AlertDialog.Builder(this).setTitle("What are you making?").setItems(new String[]{"Quick highlight · 15 seconds · logo only","Ride story · 60 seconds · speed and branding","Route tour · 60 seconds · ride data and route","Full clip · logo only"},(d,i)->applyStyle(i)).show());
  DashUi.button(this,page,"My three saved settings",v->scroll.smoothScrollTo(0,savedAnchor.getTop()));
  heading("CUSTOM EXPORT");choice("Format","social_ratio",new int[]{0,1,2,3},new String[]{"Portrait 9:16","Feed 4:5","Square 1:1","Landscape 16:9"},0);choice("Quality","social_quality",new int[]{1080,720},new String[]{"1080 · detailed","720 · smaller file"},1080);choice("Video bitrate","social_bitrate",new int[]{4,6,8,12,16},new String[]{"4 Mbps","6 Mbps","8 Mbps","12 Mbps","16 Mbps"},8);choice("Framing","social_fit",new int[]{0,1},new String[]{"Keep whole picture · add bars","Fill frame · center crop"},0);
  integer("Start at","social_start",0,86400,"seconds from start");integer("Length","social_length",15,600,"seconds, 0 = remaining clip");choice("Sound","social_mute",new int[]{0,1},new String[]{"Keep recorded audio","Mute"},0);choice("Data overlays","social_overlay",new int[]{0,1,2,3,4},new String[]{"Logo only","Speed and branding","Touring and route","All available data","My overlay settings"},0);DashUi.button(this,page,"Customize data overlays",v->startActivity(new Intent(this,OverlaySettingsActivity.class)));
  DashUi.text(this,page,"The RideDeck logo is always included. Route overlays can reveal your location history. Audio can include conversations. Check your export before sharing.",15);
  int[] size=SocialProfile.dimensions(settings.number("social_ratio",0),settings.number("social_quality",1080));DashUi.text(this,page,size[0]+" × "+size[1]+" · MP4 / H.264 · up to 30 fps · AAC when audio exists. These are practical starting presets, not upload guarantees. Platforms may crop or recompress. Center crop removes picture edges; full-picture framing preserves them.",15);
  heading("RECORDING SETUP");DashUi.button(this,page,"Prepare detailed recording",v->{if(busy())return;settings.prefs.edit().putInt("height",1080).putInt("bitrate",12).putInt("clip",256).putInt("quota",16).putString("preset","Social detail").apply();Toast.makeText(this,"Next recording: 1080p, 12 Mbps, 256 MB clips, 16 GB limit",Toast.LENGTH_LONG).show();});DashUi.button(this,page,"Recording presets and custom setup",v->startActivity(new Intent(this,SettingsActivity.class)));
  heading("MY THREE SAVED SETTINGS");savedAnchor=page.getChildAt(page.getChildCount()-1);DashUi.text(this,page,"Each named slot saves recording, camera, microphone, storage, automation, overlay and social settings. Loading applies to the next recording. The slots themselves stay saved.",15);SavedSettings saved=new SavedSettings(this);for(int i=1;i<=3;i++){final int slot=i;DashUi.button(this,page,"Slot "+slot+": "+saved.name(slot),v->slot(slot));}
  heading("EXPORT");String clip=getIntent().getStringExtra("clip");if(clip!=null){DashUi.text(this,page,"Selected: "+new File(clip).getName(),16);DashUi.button(this,page,"Open video editor",v->{if(busy())return;if(getIntent().getBooleanExtra("fromEditor",false))finish();else startActivity(new Intent(this,SocialStudioActivity.class).putExtra("project",SocialProject.selection(java.util.Collections.singletonList(clip))));});}DashUi.button(this,page,clip==null?"Choose recording":"Choose a different recording",v->startActivity(new Intent(this,ClipsActivity.class).putExtra("socialPick",true)));DashUi.button(this,page,"Back",v->finish());if("saved".equals(getIntent().getStringExtra("section"))){getIntent().removeExtra("section");scroll.post(()->scroll.scrollTo(0,savedAnchor.getTop()));}else scroll.post(()->scroll.scrollTo(0,previousScroll));
 }
 void preview(File clip){TextView label=DashUi.text(this,page,"Framing preview · "+clip.getName(),16);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setBackgroundColor(android.graphics.Color.BLACK);page.addView(image,new LinearLayout.LayoutParams(-1,(int)(240*getResources().getDisplayMetrics().density)));final int ratio=settings.number("social_ratio",0),fit=settings.number("social_fit",0),start=settings.number("social_start",0);new Thread(()->{android.media.MediaMetadataRetriever reader=new android.media.MediaMetadataRetriever();try{if(!clip.getCanonicalPath().startsWith(new ClipStore(this).root().getCanonicalPath()+File.separator)||!ClipStore.finalized(clip))throw new java.io.IOException();reader.setDataSource(clip.getPath());android.graphics.Bitmap source=reader.getFrameAtTime(start*1000000L,android.media.MediaMetadataRetriever.OPTION_CLOSEST);if(source==null)throw new java.io.IOException();int[] dimensions=SocialProfile.dimensions(ratio,720);int w=dimensions[0]/2,h=dimensions[1]/2;android.graphics.Bitmap target=android.graphics.Bitmap.createBitmap(w,h,android.graphics.Bitmap.Config.ARGB_8888);android.graphics.Canvas canvas=new android.graphics.Canvas(target);canvas.drawColor(android.graphics.Color.BLACK);float scale=fit==1?Math.max(w/(float)source.getWidth(),h/(float)source.getHeight()):Math.min(w/(float)source.getWidth(),h/(float)source.getHeight());float width=source.getWidth()*scale,height=source.getHeight()*scale;canvas.drawBitmap(source,null,new android.graphics.RectF((w-width)/2,(h-height)/2,(w+width)/2,(h+height)/2),new android.graphics.Paint(android.graphics.Paint.FILTER_BITMAP_FLAG));source.recycle();runOnUiThread(()->{if(image.isAttachedToWindow())image.setImageBitmap(target);else target.recycle();});}catch(Exception error){runOnUiThread(()->{if(label.isAttachedToWindow())label.setText("Preview unavailable · select a finalized clip");});}finally{try{reader.release();}catch(Exception ignored){}}},"DashSocialPreview").start();}
 void heading(String text){TextView title=DashUi.text(this,page,text,12);title.setTextColor(AppearancePalette.accent(RideAppearance.accentIndex(this),RideAppearance.isDark(this)));title.setPadding(12,36,12,12);}
 boolean busy(){if(RecordingService.running||RecordingService.finalizing){Toast.makeText(this,"Stop recording before loading settings or exporting",Toast.LENGTH_LONG).show();return true;}return false;}
 void custom(){settings.put("social_name","Custom");}
 void applyStyle(int i){settings.put("social_length",SocialProfile.seconds(i));settings.put("social_overlay",i==1?1:i==2?2:0);settings.put("social_start",0);int platform=settings.number("social_platform",0);settings.put("social_name",SocialProfile.PLATFORMS[Math.max(0,Math.min(7,platform))]+" · "+SocialProfile.STYLES[i]);show();}
 void choice(String title,String key,int[] values,String[] labels,int fallback){int current=settings.number(key,fallback),index=0;for(int n=0;n<values.length;n++)if(current==values[n])index=n;DashUi.button(this,page,title+": "+labels[index],v->new AlertDialog.Builder(this).setTitle(title).setItems(labels,(d,i)->{settings.put(key,values[i]);custom();show();}).show());}
 void integer(String title,String key,int fallback,int max,String hint){DashUi.button(this,page,title+": "+settings.number(key,fallback)+" "+hint,v->{EditText input=new EditText(this);input.setInputType(InputType.TYPE_CLASS_NUMBER);input.setText(String.valueOf(settings.number(key,fallback)));AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title+" · "+hint).setView(input).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{try{int value=Integer.parseInt(input.getText().toString().trim());if(value<0||value>max)throw new NumberFormatException();settings.put(key,value);custom();dialog.dismiss();show();}catch(NumberFormatException e){input.setError("Enter 0 to "+max);}}));dialog.show();});}
 void slot(int slot){SavedSettings saved=new SavedSettings(this);new AlertDialog.Builder(this).setTitle("Slot "+slot+" · "+saved.name(slot)).setItems(saved.exists(slot)?new String[]{"Load settings","Replace with current settings","Remove saved slot"}:new String[]{"Save current settings"},(d,i)->{if(!saved.exists(slot)||i==1){EditText name=new EditText(this);name.setSingleLine(true);name.setText(saved.exists(slot)?saved.name(slot):"My settings "+slot);new AlertDialog.Builder(this).setTitle("Save current app settings").setView(name).setNegativeButton("Cancel",null).setPositiveButton("Save",(a,b)->{try{String text=name.getText().toString().trim();saved.save(slot,text.isEmpty()?"My settings "+slot:text.substring(0,Math.min(40,text.length())));show();}catch(Exception e){Toast.makeText(this,"Could not save settings",Toast.LENGTH_LONG).show();}}).show();}else if(i==0){if(busy())return;new AlertDialog.Builder(this).setTitle("Load "+saved.name(slot)+"?").setMessage("Replace current recording, audio, storage, automation, overlay and social settings with this saved slot?").setNegativeButton("Cancel",null).setPositiveButton("Load",(a,b)->{try{saved.load(slot);show();}catch(Exception e){Toast.makeText(this,"Could not load settings",Toast.LENGTH_LONG).show();}}).show();}else new AlertDialog.Builder(this).setMessage("Remove this saved settings slot? Your videos are kept.").setNegativeButton("Cancel",null).setPositiveButton("Remove",(a,b)->{saved.remove(slot);show();}).show();}).show();}
}
